@Composable internal fun IposScreen(s:LensState,vm:LensViewModel,a:UiActions){
 LaunchedEffect(Unit){if(s.ipos.isEmpty())vm.loadIpos()};Label("The primary market, in focus",Violet);Text("From opening bell\nto listing day.",color=Ink,fontSize=35.sp,lineHeight=39.sp,fontWeight=FontWeight.Bold)
 var section by rememberSaveable{mutableStateOf("Official")};ChoiceRow(listOf("Official","Tracked","Applications","GMP"),section){section=it}
 when(section){
 "GMP"->GmpScreen(s,vm,a)
 "Applications"->ApplicationsScreen(s,vm,a)
 else->{var filter by rememberSaveable{mutableStateOf("Recent")};var board by rememberSaveable{mutableStateOf("All boards")};var query by rememberSaveable{mutableStateOf("")};var limit by rememberSaveable{mutableIntStateOf(25)}
  ChoiceRow(listOf("Recent","Open","Upcoming","Closed / listed"),filter){filter=it};ChoiceRow(listOf("All boards","Mainboard","SME","Unclassified"),board){board=it}
  OutlinedTextField(query,{query=it},label={Text("Search issuer / symbol")},singleLine=true,modifier=Modifier.fillMaxWidth(),leadingIcon={Icon(Icons.Rounded.Search,null)})
  Action("Refresh official issues",{vm.loadIpos(true)},icon=Icons.Rounded.Refresh);ErrorLine(s,"ipos"){vm.loadIpos(true)}
  val tracked=s.profile().tracked();val rows=if(section=="Tracked")tracked.map{old->s.ipos.firstOrNull{it.id()==old.id()}?:old}else s.ipos
  val today=LocalDate.now(ZoneId.of("Asia/Kolkata"));val matches=rows.filter{i->val phase=i.phase(today);val ok=when(filter){"Open"->phase=="Open by dates";"Upcoming"->phase=="Upcoming";"Closed / listed"->phase=="Closed"||phase=="Listed";else->i.end.isBlank()||LocalDate.parse(i.end)>=today.minusDays(120)};ok&&(board=="All boards"||ipoBoard(i)==board)&&(i.name+" "+i.symbol).contains(query,true)}
  matches.take(limit).forEach{i->LensCard(accent=if(i.phase(today)=="Open by dates")Lime else null){Label("${ipoBoard(i)} · ${i.phase(today)}",if(i.phase(today)=="Open by dates")Lime else Violet);Text(i.name,color=Ink,fontSize=20.sp,fontWeight=FontWeight.SemiBold);MetricPair("Price band",i.range.ifBlank{"Not published"},"Total subscription",if(i.subscription.isFinite())number(i.subscription)+"×"else "—");Caption("${dateText(i.start)} → ${dateText(i.end)} · ${i.symbol} / ${i.series}");Action("Explore issue",{a.ipo(i)},icon=Icons.Rounded.NorthEast)}}
  if(matches.isEmpty()&&"ipos" !in s.busy)EmptyState("No issues in this view","Try another date filter or inspect the original exchange pages. NSE coverage does not include every BSE-only issue.",Icons.Rounded.RocketLaunch)
  if(matches.size>limit)Action("Show 25 more",{limit+=25})
  s.ipoFeeds.forEach{feed->Caption("${if(feed.source.contains("upcoming"))"Upcoming"else if(feed.source.contains("past"))"Past"else "Current"} NSE feed · ${feed.rows.size} recognized issues · "+(if(feed.fetched>0)java.text.SimpleDateFormat("dd MMM HH:mm",java.util.Locale.ENGLISH).format(java.util.Date(feed.fetched))else "not downloaded")+if(feed.saved)" · saved"else "");if(feed.issue.isNotBlank())Caption(feed.issue,Pink)}
  Action("Original NSE IPO lists",{a.url(Research.IPO_PAGE)});Action("Original BSE public issues",{a.url("https://www.bseindia.com/markets/PublicIssues/IPOIssues_new.aspx")})
 }
 }
}
private fun ipoBoard(i:Research.Ipo)=when(i.series.uppercase()){ "EQ"->"Mainboard";"SM","ST","SME"->"SME";else->"Unclassified"}
@Composable internal fun IpoDetail(i:Research.Ipo,s:LensState,vm:LensViewModel,a:UiActions){
 LaunchedEffect(i.id()){vm.issueInfo(i)};val info=s.info[i.id()];Label("${i.symbol} · ${ipoBoard(i)}",Violet);Text(i.name,color=Ink,fontSize=31.sp,lineHeight=36.sp,fontWeight=FontWeight.SemiBold)
 LensCard(accent=Violet){MetricPair("Price band",i.range.ifBlank{if(info!=null)rupees(info.low)+" – "+rupees(info.high)else "—"},"Source subscription",if(i.subscription.isFinite())number(i.subscription)+"×"else "—");MetricPair("Opens",dateText(i.start),"Closes",dateText(i.end));MetricPair("Listing",dateText(i.listing),"Shares per lot",number(info?.lot?:Double.NaN,0));Action(if(s.profile().tracked(i.id()))"✓ Tracked · stop tracking"else "Track IPO & dates",{vm.task("track"){vm.profile{it.track(i,!it.tracked(i.id()))}}},primary=true,icon=Icons.Rounded.BookmarkBorder);Action("Add application / capital record",{a.form(applicationForm(i,vm))},icon=Icons.Rounded.Add);Action("Refresh issue",{vm.issueInfo(i,true)},icon=Icons.Rounded.Refresh)}
 ErrorLine(s,"issue:${i.id()}"){vm.issueInfo(i,true)}
 if(info!=null){SectionTitle("Original issue information");LensCard{info.facts.forEach{(k,v)->Label(k);Caption(v,Ink)};MetricPair("One-lot arithmetic",rupees(Research.lotCost(info.high,info.lot,1.0)),"Source lot size",number(info.lot,0));Caption("One lot is arithmetic, not an eligibility or minimum-application rule. Check the original terms for your investor category.");Action("Calculate application amount",{a.form(FormSpec("Application calculator","Illustrative amount only. Verify category rules and required lots in the offer documents.",listOf(FormField("price","Assumed bid price (₹)",if(info.high.isFinite())info.high.toString()else "",number=true),FormField("lot","Shares per lot",if(info.lot.isFinite())info.lot.toString()else "",number=true),FormField("lots","Number of lots","1",number=true)),"Calculate"){v->val amount=Research.lotCost(v.getValue("price").toDouble(),v.getValue("lot").toDouble(),v.getValue("lots").toDouble());require(amount.isFinite()){"Use positive prices and whole lot quantities"};vm.message("Application amount: ${rupees(amount)}")})});SourceNote(info.source,info.stamp,info.fetched,info.issue,a.url)}
 if(info.bids.isNotEmpty()){SectionTitle("Reported bid categories");info.bids.forEach{b->LensCard{Text(b[0],color=Ink,fontWeight=FontWeight.Medium);MetricPair("Shares bid",number(Parse.number(b[1]),0),"Applications",number(Parse.number(b[2]),0))}};Caption("Top-level counts as reported. Subcategories are not added to their parents; category subscription ratios are not inferred.")}
 }
 val history=s.snapshots.filter{it.key.startsWith("ipo-bids:${i.id()}:")}.sortedByDescending{it.retrieved}.take(8)
 if(history.isNotEmpty()){SectionTitle("Observed subscription snapshots","Only updates downloaded by this app");history.forEach{snap->val j=JSONObject(snap.payload);LensCard{Caption(snap.asOf);Caption(j.optString("summary"));Caption("Fetched "+java.text.SimpleDateFormat("dd MMM HH:mm",java.util.Locale.ENGLISH).format(java.util.Date(snap.retrieved)))}}}
 SectionTitle("Offer-document research","Original documents linked from the exchange issue page")
 val review=s.json("ipoReview:${i.id()}");LensCard{listOf("business" to "Business / financial observations","proceeds" to "Use of proceeds","fresh" to "Fresh issue / OFS","risks" to "Key risks").forEach{(k,label)->Label(label);Caption(review.optString(k).ifBlank{"Read the original offer document; no summary recorded yet."})};Action("Record document-backed review",{a.form(FormSpec("Offer-document review","Your notes, with the original source. These are not automatically extracted or verified.",listOf("business" to "Business and financial observations","proceeds" to "Use of proceeds","fresh" to "Fresh issue / OFS breakdown","risks" to "Risk factors").map{FormField(it.first,it.second,review.optString(it.first),multiline=true)}+FormField("source","Original HTTPS document",review.optString("source"))){v->require(safeUrl(v.getValue("source"))){"Original document link is required"};val j=JSONObject();v.forEach{(k,x)->j.put(k,x)};vm.save("ipoReview","ipoReview:${i.id()}",j)})});if(review.optString("source").isNotBlank())Action("Review source",{a.url(review.optString("source"))})}
 Action("Original issue, offer documents & registrar",{a.url(i.url())},primary=true,modifier=Modifier.fillMaxWidth(),icon=Icons.Rounded.OpenInNew)
 Action("NSE bid verification",{a.url("https://www.nseindia.com/invest/check-trades-bids-verify-ipo-bids")})
 Caption("Dates and status are source-reported. Application records below are your manual entries; automatic allotment verification is not included.")
 s.rows("ipoApplication").filter{JSONObject(it.json).optString("issueId")==i.id()}.forEach{ApplicationCard(it,vm,a)}
}
@Composable private fun ApplicationsScreen(s:LensState,vm:LensViewModel,a:UiActions){
 val rows=s.rows("ipoApplication");val capital=rows.mapNotNull{runCatching{Analytics.ipo(JSONObject(it.json))}.getOrNull()}
 LensCard(accent=Lime){Label("IPO capital ledger",Lime);MetricPair("Still blocked",rupees(capital.sumOf{it.blocked}),"Allotted acquisition cost",rupees(capital.sumOf{it.allottedCost}));MetricPair("Net realized P&L",rupees(capital.sumOf{it.realized}),"Net sale proceeds",rupees(capital.sumOf{it.saleProceeds}));Caption("Manual account records. Released means no longer under mandate, including amounts converted into allotted shares. It is not necessarily a bank refund.")}
 if(rows.isEmpty())EmptyState("Follow the full application","Open an IPO and add an application. Track mandate, allotment, release of funds and partial sales with account nicknames.",Icons.Rounded.AccountBalanceWallet)
 rows.forEach{ApplicationCard(it,vm,a)}
 if(rows.isNotEmpty())Action("Export application records",{val fields=listOf("name","account","status","date","applied","price","blocked","released","allotted","sold","salePrice","fees","note");a.export("MarketLens-IPO-applications.csv",fields.joinToString(",")+"\n"+rows.joinToString("\n"){r->val j=JSONObject(r.json);fields.joinToString(","){csvCell(j.optString(it))}},"text/csv")})
}
@Composable private fun ApplicationCard(r:LocalRecord,vm:LensViewModel,a:UiActions){val j=JSONObject(r.json);val c=runCatching{Analytics.ipo(j)}.getOrNull();LensCard{Label(j.optString("status"),Violet);Text(j.optString("name"),color=Ink,fontSize=18.sp,fontWeight=FontWeight.SemiBold);Caption("${j.optString("account")} · updated ${j.optString("date")}");if(c!=null){MetricPair("Still blocked",rupees(c.blocked),"Remaining allotted shares",number(c.remainingShares,0));MetricPair("Net realized P&L",rupees(c.realized),"Shares allotted",j.optString("allotted"))};Caption(j.optString("note"));Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Action("Update lifecycle",{a.form(applicationForm(null,vm,r))});Action("Delete",{vm.delete(r.id)})}}}
private fun applicationForm(i:Research.Ipo?,vm:LensViewModel,row:LocalRecord?=null):FormSpec{val j=row?.let{JSONObject(it.json)}?:JSONObject();return FormSpec("IPO application & capital","Use an account nickname. Entries are manual; no PAN, broker login or automatic registrar check. Sale fees must relate to the shares already sold.",listOf(FormField("account","Account nickname",j.optString("account","Personal")),FormField("status","Lifecycle status",j.optString("status","Applied"),listOf("Applied","Mandate pending","Blocked","Allotted","Not allotted","Released","Listed","Partly sold","Sold")),FormField("date","Last verified date · YYYY-MM-DD",j.optString("date",LocalDate.now().toString())))+listOf("applied" to "Shares applied","price" to "Issue / allotted price (₹)","blocked" to "Original mandate amount (₹)","released" to "No longer blocked, including debits (₹)","allotted" to "Shares allotted","sold" to "Shares sold so far","salePrice" to "Average sale price (₹)","fees" to "Total fees on sold shares (₹)").map{(k,label)->FormField(k,label,j.optString(k,if(k=="price"&&i?.high?.isFinite()==true)i.high.toString()else "0"),number=true)}+FormField("note","Mandate, refund and reconciliation note",j.optString("note"),multiline=true)){v->val out=JSONObject();v.forEach{(k,x)->if(k in listOf("applied","price","blocked","released","allotted","sold","salePrice","fees"))out.put(k,x.toDouble())else out.put(k,x)};require(v.getValue("account").isNotBlank());require(!LocalDate.parse(v.getValue("date")).isAfter(LocalDate.now()));Analytics.ipo(out);out.put("issueId",i?.id()?:j.getString("issueId")).put("name",i?.name?:j.getString("name"));vm.save("ipoApplication",row?.id?:java.util.UUID.randomUUID().toString(),out)}}

@Composable private fun GmpScreen(s:LensState,vm:LensViewModel,a:UiActions){
 var provider by rememberSaveable{mutableStateOf("InvestorGain")};var query by rememberSaveable{mutableStateOf("")};var limit by rememberSaveable{mutableIntStateOf(20)}
 LaunchedEffect(provider){if(provider !in s.gmp)vm.loadGmp(provider)}
 LensCard(accent=Pink){Label("Unofficial market reports",Pink);Caption("GMP is unregulated, publisher-reported and separate from exchange data. Sources can disagree. It is not a guaranteed listing return.")}
 ChoiceRow(listOf("InvestorGain","IPOWatch"),provider){provider=it;limit=20};OutlinedTextField(query,{query=it},label={Text("Filter issuer")},modifier=Modifier.fillMaxWidth(),singleLine=true);Action("Refresh $provider",{vm.loadGmp(provider,true)},icon=Icons.Rounded.Refresh);ErrorLine(s,"gmp:$provider"){vm.loadGmp(provider,true)}
 val feed=s.gmp[provider];if(feed!=null){SourceNote(feed.source,feed.stamp,feed.fetched,feed.issue,a.url);val rows=feed.rows.filter{it.name.contains(query,true)}
 rows.take(limit).forEach{g->var expanded by remember(g.id()){mutableStateOf(false)};val history=s.profile().history(g);LensCard{Label(g.provider,Violet);Text(g.name,color=Ink,fontSize=18.sp,fontWeight=FontWeight.SemiBold);MetricPair("Reported premium",rupees(g.premium),"Source issue price",rupees(g.price));Caption("Publisher row ${dateText(g.stamp)}${if(g.dates.isNotBlank())" · ${g.dates}"else ""}");Caption("Missing premiums stay unavailable; a reported zero remains zero.");Action(if(expanded)"Hide observed history"else "Observed history (${history.length()})",{expanded=!expanded});if(expanded){for(n in 0 until minOf(history.length(),12)){val h=history.getJSONObject(n);Caption("${dateText(h.optString("asOf"))} · ${rupees(Analytics.num(h,"premium"))} · observed "+java.text.SimpleDateFormat("dd MMM HH:mm",java.util.Locale.ENGLISH).format(java.util.Date(h.optLong("retrieved"))))};Action("Compare with actual listing outcome",{a.form(gmpOutcomeForm(g,history,vm))});val outcome=s.json("gmpOutcome:${g.id()}");if(outcome.has("actual")){MetricPair("Recorded first-day open",rupees(Analytics.num(outcome,"actual")),"Observed pre-listing GMP",rupees(Analytics.num(outcome,"premium")));Caption("${outcome.optString("listing")} · user-entered listing outcome · selected original source below. This is one explicitly matched observation.");Action("Outcome source",{a.url(outcome.optString("source"))})}};Action("Original publisher report",{a.url(g.url)})}}
 if(rows.size>limit)Action("Show 20 more",{limit+=20})}
 Caption("History contains only snapshots this app observed. It is not a reconstructed full GMP history. Publishers are never averaged or joined by fuzzy issuer-name matching.")
}
private fun gmpOutcomeForm(g:Research.Gmp,history:JSONArray,vm:LensViewModel)=FormSpec("GMP versus listing outcome","Explicitly verify the issuer. A pre-listing observation must already exist; post-listing GMP cannot be used as a prediction.",listOf(FormField("symbol","Confirmed NSE / BSE symbol"),FormField("listing","Actual listing date · YYYY-MM-DD"),FormField("actual","First-day opening price (₹)",number=true),FormField("source","Original exchange outcome HTTPS source"))){v->val date=LocalDate.parse(v.getValue("listing"));require(!date.isAfter(LocalDate.now()));require(Data.validSymbol(v.getValue("symbol").uppercase()));require(safeUrl(v.getValue("source")));val host=java.net.URI(v.getValue("source")).host;require(host=="www.nseindia.com"||host=="www.bseindia.com"||host=="archives.nseindia.com"||host=="nsearchives.nseindia.com"){"Use an original NSE or BSE source"};val actual=v.getValue("actual").toDouble();require(actual.isFinite()&&actual>0);val cutoff=date.atTime(9,0).atZone(ZoneId.of("Asia/Kolkata")).toInstant().toEpochMilli();val prior=(0 until history.length()).map{history.getJSONObject(it)}.filter{it.optLong("retrieved") in 1 until cutoff&&Analytics.num(it,"premium").isFinite()}.maxByOrNull{it.optLong("retrieved")};require(prior!=null){"No observed GMP snapshot predates this listing session"};vm.save("gmpOutcome","gmpOutcome:${g.id()}",JSONObject().put("symbol",v.getValue("symbol").uppercase()).put("listing",date.toString()).put("actual",actual).put("source",v.getValue("source")).put("premium",Analytics.num(prior,"premium")).put("observed",prior.optLong("retrieved")))}
